import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# CUDA implementation source
cuda_source = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda_runtime.h>

#define BLOCK_M 16
#define BLOCK_N 16
#define BLOCK_K 16

__global__ void batched_matmul_kernel(
    const float* __restrict__ A,
    const float* __restrict__ B,
    float* __restrict__ C,
    int N, int M, int K, int L
) {
    // Grid: (ceil_div(L, BLOCK_N), ceil_div(M, BLOCK_M), N)
    int batch = blockIdx.z;
    int m0 = blockIdx.y * BLOCK_M;
    int l0 = blockIdx.x * BLOCK_N;

    int tm = threadIdx.y; // 0..BLOCK_M-1
    int tl = threadIdx.x; // 0..BLOCK_N-1

    int m = m0 + tm;
    int l = l0 + tl;

    extern __shared__ float shared_mem[];
    float* As = shared_mem; // size BLOCK_M * BLOCK_K
    float* Bs = As + BLOCK_M * BLOCK_K; // size BLOCK_K * BLOCK_N

    float acc = 0.0f;

    // Offsets for A and C for this batch
    const int A_batch_offset = batch * (M * K);
    const int C_batch_offset = batch * (M * L);

    for (int k0 = 0; k0 < K; k0 += BLOCK_K) {
        // Load A tile [BLOCK_M x BLOCK_K]
        if (m < M) {
            for (int tk = 0; tk < BLOCK_K; tk += BLOCK_N) {
                int k_idx = k0 + tl + tk;
                int a_sh_idx = tm * BLOCK_K + (tl + tk);
                if ((tl + tk) < BLOCK_K && k_idx < K) {
                    As[a_sh_idx] = A[A_batch_offset + m * K + k_idx];
                } else if ((tl + tk) < BLOCK_K) {
                    As[a_sh_idx] = 0.0f;
                }
            }
        } else {
            for (int tk = 0; tk < BLOCK_K; tk += BLOCK_N) {
                int a_sh_idx = tm * BLOCK_K + (tl + tk);
                if ((tl + tk) < BLOCK_K) {
                    As[a_sh_idx] = 0.0f;
                }
            }
        }

        // Load B tile [BLOCK_K x BLOCK_N]
        for (int tk = 0; tk < BLOCK_K; tk += BLOCK_M) {
            int k_idx = k0 + tm + tk;
            int b_sh_idx = (tm + tk) * BLOCK_N + tl;
            if ((tm + tk) < BLOCK_K && k_idx < K && l < L) {
                Bs[b_sh_idx] = B[k_idx * L + l];
            } else if ((tm + tk) < BLOCK_K) {
                Bs[b_sh_idx] = 0.0f;
            }
        }

        __syncthreads();

        // Compute partial results
        if (m < M && l < L) {
            for (int kk = 0; kk < BLOCK_K; ++kk) {
                float a_val = As[tm * BLOCK_K + kk];
                float b_val = Bs[kk * BLOCK_N + tl];
                acc += a_val * b_val;
            }
        }

        __syncthreads();
    }

    if (m < M && l < L) {
        C[C_batch_offset + m * L + l] = acc;
    }
}

torch::Tensor batched_matmul(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.is_cuda(), "A must be a CUDA tensor");
    TORCH_CHECK(B.is_cuda(), "B must be a CUDA tensor");
    TORCH_CHECK(A.dtype() == torch::kFloat32, "A must be float32");
    TORCH_CHECK(B.dtype() == torch::kFloat32, "B must be float32");
    TORCH_CHECK(A.dim() == 3, "A must be 3D (N, M, K)");
    TORCH_CHECK(B.dim() == 2, "B must be 2D (K, L)");
    TORCH_CHECK(A.size(2) == B.size(0), "Inner dimensions must match: A[..., K] and B[K, ...]");

    auto A_contig = A.contiguous();
    auto B_contig = B.contiguous();

    int64_t N = A_contig.size(0);
    int64_t M = A_contig.size(1);
    int64_t K = A_contig.size(2);
    int64_t L = B_contig.size(1);

    auto options = A_contig.options();
    auto C = torch::empty({N, M, L}, options);

    dim3 block(BLOCK_N, BLOCK_M);
    dim3 grid((L + BLOCK_N - 1) / BLOCK_N, (M + BLOCK_M - 1) / BLOCK_M, N);

    size_t shared_mem_bytes = (BLOCK_M * BLOCK_K + BLOCK_K * BLOCK_N) * sizeof(float);

    cudaStream_t stream = at::cuda::getCurrentCUDAStream();

    batched_matmul_kernel<<<grid, block, shared_mem_bytes, stream>>>(
        A_contig.data_ptr<float>(),
        B_contig.data_ptr<float>(),
        C.data_ptr<float>(),
        (int)N, (int)M, (int)K, (int)L
    );

    return C;
}
"""

# CPU fallback implementation source
cpu_source = r"""
#include <torch/extension.h>

torch::Tensor batched_matmul(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(!A.is_cuda(), "A must be a CPU tensor");
    TORCH_CHECK(!B.is_cuda(), "B must be a CPU tensor");
    TORCH_CHECK(A.dtype() == torch::kFloat32, "A must be float32");
    TORCH_CHECK(B.dtype() == torch::kFloat32, "B must be float32");
    TORCH_CHECK(A.dim() == 3, "A must be 3D (N, M, K)");
    TORCH_CHECK(B.dim() == 2, "B must be 2D (K, L)");
    TORCH_CHECK(A.size(2) == B.size(0), "Inner dimensions must match: A[..., K] and B[K, ...]");

    auto A_contig = A.contiguous();
    auto B_contig = B.contiguous();

    const int64_t N = A_contig.size(0);
    const int64_t M = A_contig.size(1);
    const int64_t K = A_contig.size(2);
    const int64_t L = B_contig.size(1);

    auto C = torch::empty({N, M, L}, A_contig.options());

    auto Aacc = A_contig.accessor<float, 3>();
    auto Bacc = B_contig.accessor<float, 2>();
    auto Cacc = C.accessor<float, 3>();

    for (int64_t n = 0; n < N; ++n) {
        for (int64_t m = 0; m < M; ++m) {
            for (int64_t l = 0; l < L; ++l) {
                float sum = 0.0f;
                for (int64_t k = 0; k < K; ++k) {
                    sum += Aacc[n][m][k] * Bacc[k][l];
                }
                Cacc[n][m][l] = sum;
            }
        }
    }

    return C;
}
"""

