        name="batched_matmul_cuda_ext",
        cpp_sources=[cpp_decl],
        cuda_sources=[cuda_source],
        functions=["batched_matmul"],
        verbose=False,
        extra_cflags=["-O3"],
        extra_ldflags=[],
    )
else:
    ext = load_inline(
        name="batched_matmul_cpu_ext",
        cpp_sources=[cpu_source],
