        if A.dtype != torch.float32:
            A = A.float()
        if B.dtype != torch.float32:
            B = B.float()

        # Ensure tensors are on the same device
        if A.device != B.device:
            B = B.to(A.device)

        A = A.contiguous()
        B = B.contiguous()
        return self._op.batched_matmul(A, B)


