# Inline CUDA kernel for 3D tensor-matrix multiplication: (N, M, K) @ (K, L) -> (N, M, L)
cuda_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda_runtime.h>

#define TILE 16

// Kernel computes C = A * B where
// A: (P, K) flattened from (N*M, K)
// B: (K, L)
// C: (P, L)
__global__ void matmul3d_flat_kernel(const float* __restrict__ A,
                                     const float* __restrict__ B,
                                     float* __restrict__ C,
                                     int P, int K, int L) {
    __shared__ float As[TILE][TILE];
    __shared__ float Bs[TILE][TILE];

    int row = blockIdx.y * TILE + threadIdx.y; // [0, P)
    int col = blockIdx.x * TILE + threadIdx.x; // [0, L)

    float acc = 0.0f;

    int numTiles = (K + TILE - 1) / TILE;
    for (int t = 0; t < numTiles; ++t) {
        int a_col = t * TILE + threadIdx.x;
        int b_row = t * TILE + threadIdx.y;

        if (row < P && a_col < K) {
            As[threadIdx.y][threadIdx.x] = A[row * K + a_col];
        } else {
            As[threadIdx.y][threadIdx.x] = 0.0f;
        }

        if (b_row < K && col < L) {
            Bs[threadIdx.y][threadIdx.x] = B[b_row * L + col];
        } else {
            Bs[threadIdx.y][threadIdx.x] = 0.0f;
        }

        __syncthreads();

        #pragma unroll
        for (int k = 0; k < TILE; ++k) {
            acc += As[threadIdx.y][k] * Bs[k][threadIdx.x];
        }
        __syncthreads();
    }

    if (row < P && col < L) {
        C[row * L + col] = acc;
    }
}

torch::Tensor batched_matmul_3d_cuda(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.is_cuda(), "A must be a CUDA tensor");
    TORCH_CHECK(B.is_cuda(), "B must be a CUDA tensor");
    TORCH_CHECK(A.dim() == 3, "A must be 3D (N, M, K)");
    TORCH_CHECK(B.dim() == 2, "B must be 2D (K, L)");
    TORCH_CHECK(A.scalar_type() == at::kFloat, "A must be float32");
    TORCH_CHECK(B.scalar_type() == at::kFloat, "B must be float32");

    // Ensure contiguity
    A = A.contiguous();
    B = B.contiguous();

    const int64_t N = A.size(0);
    const int64_t M = A.size(1);
    const int64_t K = A.size(2);
    TORCH_CHECK(B.size(0) == K, "B's first dim must match A's last dim (K)");
    const int64_t L = B.size(1);

    const int64_t P = N * M;

    at::cuda::CUDAGuard device_guard(A.device());

    auto C = torch::empty({N, M, L}, A.options());

    dim3 block(TILE, TILE);
    dim3 grid((L + TILE - 1) / TILE, (P + TILE - 1) / TILE);

    cudaStream_t stream = at::cuda::getCurrentCUDAStream();

    const float* Aptr = A.data_ptr<float>();
    const float* Bptr = B.data_ptr<float>();
    float* Cptr = C.data_ptr<float>();

    matmul3d_flat_kernel<<<grid, block, 0, stream>>>(Aptr, Bptr, Cptr, (int)P, (int)K, (int)L);

    // Optional: check for launch errors
    TORCH_CHECK(cudaGetLastError() == cudaSuccess, "CUDA kernel launch failed");

    return C;
}
